            with urllib.request.urlopen(req, timeout=30) as resp:
                AUTH = json.load(resp)['token']
                return
        except urllib.error.HTTPError as exc:
            body = exc.read().decode('utf-8', 'replace')
            if exc.code == 429:
                delay = wait_seconds(exc.headers, body, min(2 ** (attempt - 1), 10))
                print(f'token rate-limited; waiting {delay:g}s', file=sys.stderr)
                time.sleep(delay)
            else:
                delay = min(2 ** (attempt - 1), 10)
                print(f'token request HTTP {exc.code}; retrying in {delay:g}s', file=sys.stderr)
                time.sleep(delay)
        except Exception as exc:
            delay = min(2 ** (attempt - 1), 10)
            print(f'token request failed ({exc}); retrying in {delay:g}s', file=sys.stderr)
            time.sleep(delay)
    raise RuntimeError('could not obtain a token after retries')


