    if AUTH is None:
        get_token()
    for attempt in range(1, 31):
        req = urllib.request.Request(BASE + path, headers={'Authorization': 'Bearer ' + AUTH})
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return json.load(resp)
        except urllib.error.HTTPError as exc:
            body = exc.read().decode('utf-8', 'replace')
            if exc.code in (401, 403):
                print(f'{path}: token rejected/expired; refreshing', file=sys.stderr)
                get_token()
                continue
            if exc.code == 429:
                delay = wait_seconds(exc.headers, body, min(2 ** (attempt - 1), 10))
                print(f'{path}: rate-limited; waiting {delay:g}s', file=sys.stderr)
                time.sleep(delay)
                continue
            if exc.code >= 500:
                delay = min(2 ** (attempt - 1), 10)
                print(f'{path}: HTTP {exc.code}; retrying in {delay:g}s', file=sys.stderr)
                time.sleep(delay)
                continue
            raise RuntimeError(f'{path}: HTTP {exc.code}: {body}')
        except Exception as exc:
            delay = min(2 ** (attempt - 1), 10)
            print(f'{path}: request failed ({exc}); retrying in {delay:g}s', file=sys.stderr)
            time.sleep(delay)
    raise RuntimeError(f'{path}: exhausted retries')


start = dt.datetime(2025, 3, 1, tzinfo=dt.timezone.utc)
end = dt.datetime(2025, 6, 1, tzinfo=dt.timezone.utc)
seen = set()
orders = []
duplicates_skipped = 0
path = '/orders?page=1'
page_count = 0
while path:
    page = get_json(path)
    page_count += 1
    for order in page['items']:
        order_id = order['id']
        if order_id in seen:
