    cid = order['customer_id']
    if cid not in customers:
        customers[cid] = get_json('/customers/' + cid)

by_region = {'north': 0, 'south': 0, 'east': 0, 'west': 0}
for order in orders:
    customer = customers[order['customer_id']]
    amount = Decimal(order['amount_cents'])
    discount = Decimal(customer['discount_pct'])
    discounted = (amount * (Decimal(100) - discount) / Decimal(100)).quantize(Decimal('1'), rounding=ROUND_HALF_UP)
    by_region[customer['region']] += int(discounted)

total = sum(by_region.values())
